<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigSenderEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigSenderEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withSenderEmail,
 * getSenderEmail/senderEmail accessors, and isSenderEmailChanged with/without original.
 */
class SmtpOutboundConfigSenderEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSenderEmail creates a new instance with the SenderEmail set
     * from a string value, and getSenderEmail returns the primitive string.
     */
    public function testWithSenderEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigSenderEmailAccessorUnitTest();

        // Act
        $result = $holder->withSenderEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getSenderEmail());
    }
    /**
     * Asserts that withsenderEmail has access to the value object
     * from a string value, and getSenderEmail returns the primitive string.
     */
    public function testWithSenderEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigSenderEmailAccessorUnitTest();

        // Act
        $result = $holder->withSenderEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->senderEmail()->value());
    }
    public function testChangedSenderEmail(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigSenderEmailAccessorUnitTest()->withSenderEmail('one');
        $original = $holder->withSenderEmail('one');
        $same = $holder->withSenderEmail('one');
        $modified = $holder->withSenderEmail('other');

        // Act
        $withSame = $original->isSenderEmailChanged($same);
        $withDiferent = $original->isSenderEmailChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigSenderEmailAccessorUnitTest
{
    use SmtpOutboundConfigSenderEmailAccessor;
}
